const dictionaries: Record<EfestoLocale, Record<string, string>> = { es, en, pt };

type EfestoLocaleContextValue = {
  locale: EfestoLocale;
  setLocale: (locale: EfestoLocale) => void;
  t: (key: string, values?: Record<string, string | number>) => string;
};

const EfestoLocaleContext = createContext<EfestoLocaleContextValue | null>(null);

function interpolate(value: string, values?: Record<string, string | number>) {
  if (!values) return value;
  return value.replace(/\{\{(\w+)\}\}/g, (_, key: string) => String(values[key] ?? ''));
}

export function EfestoLocaleProvider({ children }: { children: ReactNode }) {
  const [locale, setLocaleState] = useState<EfestoLocale>('es');

  useEffect(() => {
    const stored = window.localStorage.getItem(EFESTO_LOCALE_STORAGE_KEY);
    if (stored === 'es' || stored === 'en' || stored === 'pt') setLocaleState(stored);
  }, []);

  useEffect(() => {
    document.documentElement.lang = locale;
  }, [locale]);

  const value = useMemo<EfestoLocaleContextValue>(() => ({
    locale,
    setLocale: (next) => {
      setLocaleState(next);
      window.localStorage.setItem(EFESTO_LOCALE_STORAGE_KEY, next);
    },
    t: (key, values) => interpolate(dictionaries[locale][key] ?? dictionaries.es[key] ?? key, values),
  }), [locale]);

  return <EfestoLocaleContext.Provider value={value}>{children}</EfestoLocaleContext.Provider>;
}

export function useEfestoLocale() {
  const context = useContext(EfestoLocaleContext);
  if (!context) throw new Error('useEfestoLocale must be used inside EfestoLocaleProvider');
  return context;
}
